import React, { useEffect, useMemo, useState } from "react";
import { useOutletContext } from "react-router-dom";

// === Rates from Excel (unchanged) ===
const RATE_R1 = 27.85; // G37
const RATE_R2 = 66.63; // G38

const roundUp2 = (x) => Math.ceil((Number(x) || 0) * 100) / 100;
const currentMonthYYYYMM = () => {
  const d = new Date();
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}`;
};


const round2 = (x) => Math.round((Number(x) || 0) * 100) / 100;


  // CHANGE: TDM sub-sections + row model
  const TDM_SUBS = [
    "Robot-With Selenium",
    "Robot-With playwright",
    "UFT",
    "Standalone Robot",
    "Other-Utility",
 ];
  const mkTdmRow = () => ({
    Dropdown1: "",                    // Application
    Dropdown2: currentMonthYYYYMM(),  // ROI month (YYYY-MM)
    Dropdown3: "",                    // Savings Category
    N: 0, N1: 0, N2: 0, N3: 0,
    PD1: 0, C1: 0, PD2: 0, C2: 0, Savings: 0,
   Comment: ""                       // CHANGE: comment field for DB save
  });
  const [tdmActive, setTdmActive] = useState(TDM_SUBS[0]);
  const [tdmRowsBySub, setTdmRowsBySub] = useState(
    Object.fromEntries(TDM_SUBS.map((k) => [k, [mkTdmRow()]]))
  );
 const recomputeTdm = (rows) =>
    rows.map((r) => {
      const PD1 = r.N1 ? roundUp2(r.N / r.N1) : 0;
      const C1  = round2(PD1 * 8 * (RATE_R1 + 0.15 * RATE_R2));  // CHANGE: round to 2 decimals
     const PD2 = r.N2 ? roundUp2(r.N / r.N2) : 0;
      const C2  = round2(PD2 * 8 * (RATE_R1 + 0.15 * RATE_R2));  // CHANGE: round to 2 decimals
      const S   = round2((C1 - C2) * (Number(r.N3) || 0));       // CHANGE: round to 2 decimals
      return { ...r, PD1, C1, PD2, C2, Savings: S };
   });
  const updateTdmRow = (subKey, idx, key, value) => {
    setTdmRowsBySub((prev) => {
      const copy = { ...prev };
      const rows = [...copy[subKey]];
      rows[idx] = { ...rows[idx], [key]: value };
      copy[subKey] = recomputeTdm(rows);
      return copy;
    });
  };
  const addTdmRowAfter = (subKey, idx) => {
    setTdmRowsBySub((prev) => {
      const copy = { ...prev };
      const rows = [...copy[subKey]];
      rows.splice(idx + 1, 0, mkTdmRow());
      copy[subKey] = recomputeTdm(rows);
      return copy;
    });
  };
  const deleteTdmRowAt = (subKey, idx) => {
   setTdmRowsBySub((prev) => {
      const copy = { ...prev };
      const rows = [...copy[subKey]];
      rows.splice(idx, 1);
      if (!rows.length) rows.push(mkTdmRow());
      copy[subKey] = recomputeTdm(rows);
     return copy;
    });
  };



// Default row for automation sub-tabs (kept same fields; renamed dropdown labels in UI)
const mkAutoRow = () => ({
  Dropdown1: "",       // Application
  Dropdown2: currentMonthYYYYMM(), // ROI month
  Dropdown3: "",       // Savings Category
  N: 100,
  N1: 100,
  N2: 100,
  N3: 100,
  PD1: 0,
  C1: 0,
  PD2: 0,
  C2: 0,
  Savings: 0,
});

// compact cell widths kept
const sm = { width: 110, padding: "4px 6px" };
const smSel = { width: 160, padding: "4px 6px" };
const cell = { display: "flex", flexDirection: "column", gap: 2, minWidth: 160 };

export default function ProjectSavingsTab() {
	
	
  // ======= Get project context for Applications list & display the csv values in dropdown=======
  const { projectDetails, intakeNumber } = useOutletContext() || {};
  const applicationOptions = React.useMemo(() => {
    const csv = projectDetails?.application || "";
    // split comma-separated, trim, unique
    const parts = csv
      .split(",")
      .map((s) => s.trim())
      .filter(Boolean);
    return Array.from(new Set(parts));
  }, [projectDetails]);

  // ======= TDM Savings (now also includes the 3 dropdowns) =======
  const [tdm, setTdm] = useState({
    Dropdown1: "", // Application
    Dropdown2: currentMonthYYYYMM(), // ROI month
    Dropdown3: "", // Savings Category
    N: 0,
    N1: 0,
    N2: 0,
    N3: 0,
    PD1: 0,
    C1: 0,
    PD2: 0,
    C2: 0,
    Savings: 0,
  });

  // Auto-derived TDM numbers (unchanged logic)
  useEffect(() => {
    const PD1 = tdm.N1 ? roundUp2(tdm.N / tdm.N1) : 0;
    const C1 = PD1 * 8 * (RATE_R1 + 0.15 * RATE_R2);
    const PD2 = tdm.N2 ? roundUp2(tdm.N / tdm.N2) : 0;
    const C2 = PD2 * 8 * (RATE_R1 + 0.15 * RATE_R2);
    const S = (C1 - C2) * (Number(tdm.N3) || 0);
    setTdm((p) => ({ ...p, PD1, C1, PD2, C2, Savings: S }));
  }, [tdm.N, tdm.N1, tdm.N2, tdm.N3]);

  // ======= 7 automation sub-tabs (unchanged categories) =======
  const SUB_TABS = [
    "Conformiq-Robot",
    "Standalone (Robot/Selenium)",
    "SOA",
    "UFT",
    "Java",
    "Python",
    "Utilities",
  ];
  const [activeSub, setActiveSub] = useState(SUB_TABS[0]);

  const [rowsBySub, setRowsBySub] = useState(() =>
    Object.fromEntries(SUB_TABS.map((k) => [k, [mkAutoRow()]]))
  );

  // recompute per row (unchanged math)
  const recomputeAuto = (rows, coeff = 0.25) =>
    rows.map((r) => {
      const PD1 = r.N1 ? roundUp2(r.N / r.N1) : 0;
      const C1 = PD1 * 8 * (RATE_R1 + coeff * RATE_R2);
      const PD2 = r.N2 ? Number(r.N) / Number(r.N2) : 0;
      const C2 = PD2 * 8 * (RATE_R1 + coeff * RATE_R2);
      const Savings = (C1 - C2) * (Number(r.N3) || 0);
      return { ...r, PD1, C1, PD2, C2, Savings };
    });

  const updateRow = (subKey, idx, key, value) => {
    setRowsBySub((prev) => {
      const copy = { ...prev };
      const rows = [...copy[subKey]];
      rows[idx] = { ...rows[idx], [key]: value };
      copy[subKey] = recomputeAuto(rows);
      return copy;
    });
  };

  // NEW: add a row next to a specific row
  const addRowAfter = (subKey, idx) => {
    setRowsBySub((prev) => {
      const copy = { ...prev };
      const rows = [...copy[subKey]];
      rows.splice(idx + 1, 0, mkAutoRow());
      copy[subKey] = recomputeAuto(rows);
      return copy;
    });
  };

  // NEW: delete a specific row (keep at least 1)
  const deleteRowAt = (subKey, idx) => {
    setRowsBySub((prev) => {
      const copy = { ...prev };
      const rows = [...copy[subKey]];
      rows.splice(idx, 1);
      if (rows.length === 0) rows.push(mkAutoRow());
      copy[subKey] = recomputeAuto(rows);
      return copy;
    });
  };

  const autoSavingsTotal = useMemo(() => {
    let total = 0;
    Object.values(rowsBySub).forEach((rows) =>
      rows.forEach((r) => (total += Number(r.Savings) || 0))
    );
    return total;
  }, [rowsBySub]);

  // === DROPDOWNS ===
  const DROPDOWN_OPTIONS_1 = applicationOptions; // <Application> from projects.application
  const DROPDOWN_OPTIONS_2 = null; // ROI month is a calendar (type="month")
  
    const TDM_SAVINGS_CATEGORIES = [
      "mmtg Deal creation",
      "CLASS deal creation",
      "Savvy Deal creation",
      "Other Deal/Test data creation",
    ];
  

  const onSave = () => {
    // Same placeholder save; logic unchanged
    console.log("Save Project Savings:", { tdm, rowsBySub });
  };

  const renderAutoRow = (subKey, r, i) => (
    <div
      key={`${subKey}-${i}`}
      style={{
        display: "flex",
        gap: 10,
        alignItems: "flex-start",
        flexWrap: "wrap",
        marginBottom: 8,
        borderBottom: "1px dashed #e5e7eb",
        paddingBottom: 8,
      }}
    >
      {/* NEW: row-local controls on the right */}
      <div style={{ marginLeft: "auto", display: "flex", gap: 8 }}>
        <button className="btn-red" onClick={() => addRowAfter(subKey, i)}>
          &lt;Add Row&gt;
        </button>
        <button className="btn-red" onClick={() => deleteRowAt(subKey, i)}>
          &lt;Delete Row&gt;
        </button>
      </div>

      {/* Dropdown1 => Application */}
      <div style={cell}>
        <label className="tab-label tab-label-green">Application</label>
        <select
          className="select-red"
          style={smSel}
          value={r.Dropdown1}
          onChange={(e) => updateRow(subKey, i, "Dropdown1", e.target.value)}
        >
          <option value="">{`<Application>`}</option>
          {DROPDOWN_OPTIONS_1.map((o) => (
            <option key={o} value={o}>
              {o}
            </option>
          ))}
        </select>
      </div>

      {/* Dropdown2 => ROI month (calendar) */}
      <div style={cell}>
        <label className="tab-label tab-label-green">ROI month</label>
        <input
          type="month"
          className="tab-input"
          style={smSel}
          value={r.Dropdown2}
          onChange={(e) => updateRow(subKey, i, "Dropdown2", e.target.value)}
        />
      </div>

      {/* Dropdown3 => Savings Category */}
      <div style={cell}>
        <label className="tab-label tab-label-green">Savings Category</label>
        <select
          className="select-red"
          style={smSel}
          value={r.Dropdown3}
          onChange={(e) => updateRow(subKey, i, "Dropdown3", e.target.value)}
        >
          <option value="">{`<Savings Category>`}</option>
          {DROPDOWN_OPTIONS_3.map((o) => (
            <option key={o} value={o}>
              {o}
            </option>
          ))}
        </select>
      </div>

      {/* labeled inputs per Excel (unchanged math/labels) */}
      <div style={cell}>
        <label className="tab-label tab-label-green">N (Total Count)</label>
        <input
          className="tab-input"
          style={sm}
          type="number"
          value={r.N}
          onChange={(e) => updateRow(subKey, i, "N", Number(e.target.value))}
        />
      </div>
      <div style={cell}>
        <label className="tab-label tab-label-green">N1 (Manual/day)</label>
        <input
          className="tab-input"
          style={sm}
          type="number"
          value={r.N1}
          onChange={(e) => updateRow(subKey, i, "N1", Number(e.target.value))}
        />
      </div>
      <div style={cell}>
        <label className="tab-label tab-label-orange">PD1</label>
        <input className="tab-input tab-input-orange" style={sm} value={r.PD1} disabled />
      </div>
      <div style={cell}>
        <label className="tab-label tab-label-orange">C1</label>
        <input className="tab-input tab-input-orange" style={sm} value={r.C1} disabled />
      </div>
      <div style={cell}>
        <label className="tab-label tab-label-green">N2 (Auto/day)</label>
        <input
          className="tab-input"
          style={sm}
          type="number"
          value={r.N2}
          onChange={(e) => updateRow(subKey, i, "N2", Number(e.target.value))}
        />
      </div>
      <div style={cell}>
        <label className="tab-label tab-label-orange">PD2</label>
        <input className="tab-input tab-input-orange" style={sm} value={r.PD2} disabled />
      </div>
      <div style={cell}>
        <label className="tab-label tab-label-orange">C2</label>
        <input className="tab-input tab-input-orange" style={sm} value={r.C2} disabled />
      </div>
      <div style={cell}>
        <label className="tab-label tab-label-green">N3 (Cycles)</label>
        <input
          className="tab-input"
          style={sm}
          type="number"
          value={r.N3}
          onChange={(e) => updateRow(subKey, i, "N3", Number(e.target.value))}
        />
      </div>
      <div style={cell}>
        <label className="tab-label tab-label-orange">Savings</label>
        <input className="tab-input tab-input-orange" style={sm} value={r.Savings} disabled />
      </div>
    </div>
  );

  return (
    <div className="tab-wrap">
      {/* Keep ONLY one Save button per sub-tab at the TOP */}
      <div style={{ display: "flex", justifyContent: "flex-end", marginBottom: 10 }}>
        <button className="btn-red" onClick={onSave}>
          &lt;Save all&gt;
        </button>
      </div>

      {/* ======= TDM Savings (with 3 dropdowns added) ======= */}
      <div className="tab-section tab-section-yellow">TDM Savings</div>
	  
	        <div className="tab-section tab-section-yellow">TDM Savings</div>
	        {/* CHANGE: TDM framework buttons */}
	        <div style={{ display: "flex", gap: 8, flexWrap: "wrap", margin: "8px 0 12px" }}>
	          {TDM_SUBS.map((k) => (
	            <button
	              key={k}
	              className="btn-red"
	              onClick={() => setTdmActive(k)}
	             style={{ opacity: tdmActive === k ? 1 : 0.65 }}
	            >
	              {k}
	            </button>
	         ))}
	        </div>
	  
	  
      <div
        style={{
          display: "flex",
          gap: 12,
          flexWrap: "wrap",
          alignItems: "flex-start",
          marginBottom: 10,
        }}
      >
        {/* Application */}
        <div style={cell}>
          <label className="tab-label tab-label-green">Application</label>
          <select
            className="select-red"
            style={smSel}
            value={tdm.Dropdown1}
            onChange={(e) => setTdm({ ...tdm, Dropdown1: e.target.value })}
          >
            <option value="">{`<Application>`}</option>
            {applicationOptions.map((o) => (
              <option key={o} value={o}>
                {o}
              </option>
            ))}
          </select>
        </div>

        {/* ROI month */}
        <div style={cell}>
          <label className="tab-label tab-label-green">ROI month</label>
          <input
            type="month"
            className="tab-input"
            style={smSel}
            value={tdm.Dropdown2}
            onChange={(e) => setTdm({ ...tdm, Dropdown2: e.target.value })}
          />
        </div>

        {/* Savings Category */}
        <div style={cell}>
          <label className="tab-label tab-label-green">Savings Category</label>
          <select
            className="select-red"
            style={smSel}
            value={tdm.Dropdown3}
            onChange={(e) => setTdm({ ...tdm, Dropdown3: e.target.value })}
          >
            <option value="">{`<Savings Category>`}</option>
            {[
              "Test case Created",
              "Test Case Executed - DIT",
              "Test Case Executed - SIT",
              "Test Case Executed - UAT",
            ].map((o) => (
              <option key={o} value={o}>
                {o}
              </option>
            ))}
          </select>
        </div>

        {/* numeric inputs (unchanged) */}
        <div style={cell}>
          <label className="tab-label tab-label-green">N (Total deal count)</label>
          <input
            className="tab-input"
            style={sm}
            type="number"
            value={tdm.N}
            onChange={(e) => setTdm({ ...tdm, N: Number(e.target.value) })}
          />
        </div>
        <div style={cell}>
          <label className="tab-label tab-label-green">N1 (Manual/day)</label>
          <input
            className="tab-input"
            style={sm}
            type="number"
            value={tdm.N1}
            onChange={(e) => setTdm({ ...tdm, N1: Number(e.target.value) })}
          />
        </div>
        <div style={cell}>
          <label className="tab-label tab-label-orange">PD1 = ROUNDUP(N/N1,2)</label>
          <input className="tab-input tab-input-orange" style={sm} value={tdm.PD1} disabled />
        </div>
        <div style={cell}>
          <label className="tab-label tab-label-orange">C1 = PD1*8*(R1+0.15*R2)</label>
          <input className="tab-input tab-input-orange" style={sm} value={tdm.C1} disabled />
        </div>
        <div style={cell}>
          <label className="tab-label tab-label-green">N2 (Avg Automation/day)</label>
          <input
            className="tab-input"
            style={sm}
            type="number"
            value={tdm.N2}
            onChange={(e) => setTdm({ ...tdm, N2: Number(e.target.value) })}
          />
        </div>
        <div style={cell}>
          <label className="tab-label tab-label-orange">PD2 = ROUNDUP(N/N2,2)</label>
          <input className="tab-input tab-input-orange" style={sm} value={tdm.PD2} disabled />
        </div>
        <div style={cell}>
          <label className="tab-label tab-label-orange">C2 = PD2*8*(R1+0.15*R2)</label>
          <input className="tab-input tab-input-orange" style={sm} value={tdm.C2} disabled />
        </div>
        <div style={cell}>
          <label className="tab-label tab-label-green">N3 (Number of cycles)</label>
          <input
            className="tab-input"
            style={sm}
            type="number"
            value={tdm.N3}
            onChange={(e) => setTdm({ ...tdm, N3: Number(e.target.value) })}
          />
        </div>
        <div style={cell}>
          <label className="tab-label tab-label-orange">Savings = (C1 - C2) * N3</label>
          <input className="tab-input tab-input-orange" style={sm} value={tdm.Savings} disabled />
        </div>
      </div>

      {/* Optional grand total (unchanged) */}
      <div style={{ display: "flex", gap: 12, marginTop: 10 }}>
        <div style={cell}>
          <label className="tab-label tab-label-orange">Automation Savings Total</label>
          <input className="tab-input tab-input-orange" style={sm} value={autoSavingsTotal} disabled />
        </div>
      </div>

      {/* ======= 7 sub-tabs selector (unchanged) ======= */}
      <div className="tab-section tab-section-yellow">Automation Savings — Breakdown</div>
      <div style={{ display: "flex", gap: 8, flexWrap: "wrap", marginBottom: 10 }}>
        {SUB_TABS.map((k) => (
          <button
            key={k}
            className="btn-red"
            onClick={() => setActiveSub(k)}
            style={{ opacity: activeSub === k ? 1 : 0.65 }}
          >
            {k}
          </button>
        ))}
      </div>

      {/* rows for active sub-tab (each row has Add/Delete controls on the right) */}
      <div>{rowsBySub[activeSub].map((r, i) => renderAutoRow(activeSub, r, i))}</div>
    </div>
  );
}
